# frozen_string_literal: true

require "lutaml/model"

module Latexmath
  # The typed LaTeX language model, declared with LutaML Model.
  #
  # Latexmath.parse returns a Model::Document. Its classes
  # (lib/latexmath/model/nodes.rb) are generated by scripts/generate_model.rb
  # from the capture shapes of the normalized grammar: every capture holds
  # one kind, so each class has one attribute per capture key and
  # lutaml-model builds the whole tree from the declared attribute types
  # (Document.new on the grammar's model binding). No code here walks the
  # parse tree. See docs/model-contract.adoc.
  module Model
  end
end

require_relative "model/nodes"

module Latexmath
  module Model
    # The symbol table entry of a symbol is looked up from its spelling,
    # stripped, as in the legacy transform (data/latex-symbols.json, read by
    # Latexmath::Symbols). A spelling the table lacks is a plain symbol of
    # its own text, kind "symbol".
    class MathSymbol
      # The Symbols::Entry for #spelling.
      def entry
        Latexmath::Symbols.resolve(spelling.to_s)
      end

      # The Unicode text the symbol stands for.
      def value
        entry.value
      end

      # "symbol", "open" or "close".
      def kind
        entry.kind
      end
    end
  end
end
